export function createAsset({ THREE }) {
  const binary = decodeBase64(BINARY_CHUNK_BASE64);
  const materials = createMaterials(THREE);
  const group = new THREE.Group();
  group.name = "Red truck";

  const scene = GLTF_MODEL.scenes[GLTF_MODEL.scene] ?? GLTF_MODEL.scenes[0];
  for (const nodeIndex of scene.nodes ?? []) {
    group.add(createNode(THREE, binary, materials, nodeIndex));
  }

  return group;
}

function createNode(THREE, binary, materials, nodeIndex) {
  const node = GLTF_MODEL.nodes[nodeIndex];
  const object = node.mesh === undefined ? new THREE.Group() : createMesh(THREE, binary, materials, node.mesh, node.name);
  object.name = node.name ?? object.name;

  if (node.translation) object.position.fromArray(node.translation);
  if (node.rotation) object.quaternion.fromArray(node.rotation);
  if (node.scale) object.scale.fromArray(node.scale);
  if (node.matrix) object.matrix.fromArray(node.matrix);
  if (node.matrix) object.matrix.decompose(object.position, object.quaternion, object.scale);

  for (const childIndex of node.children ?? []) object.add(createNode(THREE, binary, materials, childIndex));
  return object;
}

function createMesh(THREE, binary, materials, meshIndex, nodeName = "") {
  const meshDef = GLTF_MODEL.meshes[meshIndex];
  const meshes = meshDef.primitives.map((primitive, primitiveIndex) => {
    const geometry = new THREE.BufferGeometry();
    geometry.setAttribute("position", createAttribute(THREE, binary, primitive.attributes.POSITION));
    if (primitive.attributes.NORMAL !== undefined) geometry.setAttribute("normal", createAttribute(THREE, binary, primitive.attributes.NORMAL));
    if (primitive.attributes.TEXCOORD_0 !== undefined) geometry.setAttribute("uv", createAttribute(THREE, binary, primitive.attributes.TEXCOORD_0));
    if (primitive.indices !== undefined) geometry.setIndex(createIndexAttribute(THREE, binary, primitive.indices));
    if (!geometry.getAttribute("normal")) geometry.computeVertexNormals();

    const mesh = new THREE.Mesh(geometry, materialForNode(materials, nodeName));
    mesh.name = primitiveIndex === 0 ? meshDef.name ?? nodeName : (meshDef.name ?? nodeName) + "-" + (primitiveIndex + 1);
    return mesh;
  });

  if (meshes.length === 1) return meshes[0];
  const group = new THREE.Group();
  group.name = meshDef.name ?? nodeName;
  group.add(...meshes);
  return group;
}

